Enqueue
            bool Queue::enqueue(double x) {
               if (isFull()) {
                     cout << "Error: the queue is full." << endl;
                     return false;
               }
               else {
                     // calculate the new rear position (circular)
                     rear = (rear + 1) % maxSize;
                     // insert new item
                     values[rear] = x;
                     // update counter
                     counter++;
                     return true;
               }
            }
