Dequeue
            bool Queue::dequeue(double & x) {
                   if (isEmpty()) {
                           cout << "Error: the queue is empty." << endl;
                           return false;
                   }
                   else {
                           // retrieve the front item
                           x = values[front];
                           // move front
                           front = (front + 1) % maxSize;
                           // update counter
                           counter--;
                           return true;
                   }
            }
